public class TFMOrderListLineSelectionAttribute extends SysAttribute implements SysExtensionIAttribute
{
    MethodName	methodName;
    TFMPageID	pageId;

}

Method.Source:
void new(TFMPageID	_pageId, MethodName _methodName)
{
    super();

    methodName = _methodName;
    pageId = _pageId;

}

public MethodName parmMethodName(MethodName	_methodName = methodName)
{
    methodName = _methodName;

    return methodName;
}

public TFMPageID parmPageID(TFMPageID	_pageId = pageId)
{
    pageId = _pageId;

    return pageId;
}
